function formatDate(dateStr) {
    if (!dateStr) return '—';
    try {
        return new Intl.DateTimeFormat('en-US', {
            month: 'short',
            day: 'numeric',
            year: 'numeric'
        }).format(new Date(dateStr));
    } catch  {
        return '—';
    }
}
function generateId() {
    return 'tpl-' + Math.random().toString(36).substring(2, 9);
}
